const runStep = (
  step: StepInput,
  customer: Customer,
  steps: StepInput[],
  index: number,
  paidOutByPolicy: Map<number, number>,
): StepResult => {
  if (isQuoteStep(step)) {
    return priceQuote(step, customer, isFollowUpContract(steps, index));
  }
  if (isClaimStep(step)) {
    return settleClaim(
      step,
      quoteStepAt(steps, step.policy).items,
      paidOutByPolicy.get(step.policy) ?? 0,
    );
  }
  throw new Error(`Unsupported step op: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  // Claims consume their policy's cap as the scenario runs, so the payouts made
  // so far against each policy have to be carried across steps.
  const paidOutByPolicy = new Map<number, number>();
  const results = scenario.steps.map((step, index) => {
    const result = runStep(
      step,
      scenario.customer,
      scenario.steps,
      index,
      paidOutByPolicy,
    );
    if (isClaimStep(step)) {
      const previous = paidOutByPolicy.get(step.policy) ?? 0;
      paidOutByPolicy.set(step.policy, previous + (result as ClaimResult).payout);
    }
    return result;
  });

  return { results };
};

